server wson con reintentos.body:
server wson ${1:nombre} =
    -> to: ${2:"http://..."}
    -> content: ${3:valor}
    -> retries: ${4:3}
    -> retryDelayMs: ${5:500}

server wson cifrado.body:
server wson ${1:nombre} =
    -> to: ${2:"http://..."}
    -> content: ${3:valor}
    -> secret: ${4:"clave-compartida"}
    -> encrypt: true
